            case 122: o.enable_rate_guide_deltaq = unchecked((uint)v); break;
            case 123: o.force_video_mode = unchecked((uint)v); break;
            case 124: o.force_max_q = unchecked((uint)v); break;
            case 125: o.chroma_sample_position = unchecked((int)v); break;
            case 126: o.qm_min = unchecked((uint)v); break;
            case 127: o.qm_max = unchecked((uint)v); break;
            case 128: o.noise_block_size = unchecked((int)v); break;
            case 129: o.enable_dnl_denoising = unchecked((int)v); break;
            case 130: o.static_thresh = unchecked((uint)v); break;
            default: throw new ArgumentOutOfRangeException(nameof(id));
        }
    }

}
